import {
  ArrowLeft,
  BookmarkPlus,
  Check,
  GraduationCap,
  Newspaper,
  Quote,
} from "lucide-react";
import { AnimatePresence, motion } from "motion/react";
import { useState } from "react";
import { cn } from "../../lib/cn";
import "./words-explorer.css";

export interface CollectedWord {
  id: string;
  title: string;
  meta: string;
  kind: "save" | "library";
  path?: string;
}

interface WordSense {
  id: string;
  label: string;
  meaning: string;
  definition: string;
  collocations: string[];
  synonyms: string[];
  origin: string;
  example: string;
  news: string;
  academic: string;
  literary: string;
}

const WORD = {
  term: "territory",
  pronunciation: "/ˈterətri/",
  partOfSpeech: "noun",
};

const SENSES: WordSense[] = [
  {
    id: "land",
    label: "land",
    meaning: "领土；领地",
    definition:
      "land that is owned or controlled by a country, ruler, or group",
    collocations: [
      "disputed territory",
      "sovereign territory",
      "claim territory",
    ],
    synonyms: ["land", "landmass", "realm"],
    origin:
      "From Latin territorium, originally meaning the land around a town.",
    example:
      "The island remains a disputed territory in the region.",
    news:
      "Both countries renewed talks over the coastal territory this week.",
    academic:
      "Territorial boundaries are shaped by political power as well as geography.",
    literary:
      "The wind moved across a territory that no map had ever named.",
  },
  {
    id: "area",
    label: "area",
    meaning: "区域；范围",
    definition:
      "a particular area of land, activity, knowledge, or experience",
    collocations: [
      "familiar territory",
      "uncharted territory",
      "enter new territory",
    ],
    synonyms: ["area", "region", "zone"],
    origin:
      "The sense of an abstract area developed from the physical meaning of land.",
    example:
      "Online learning was unfamiliar territory for many teachers.",
    news:
      "The company is moving into territory previously dominated by local firms.",
    academic:
      "The study enters a territory where linguistics and psychology overlap.",
    literary:
      "Memory carried her back into familiar territory.",
  },
  {
    id: "field",
    label: "field",
    meaning: "领域；活动范围",
    definition:
      "an area of study, work, or activity in which someone operates",
    collocations: [
      "new territory",
      "professional territory",
      "marketing territory",
    ],
    synonyms: ["field", "domain", "sphere"],
    origin:
      "The metaphor of land was extended to describe areas of knowledge and work.",
    example:
      "Artificial intelligence has entered the territory of creative writing.",
    news:
      "The deal takes the retailer into unfamiliar financial territory.",
    academic:
      "Translation studies often crosses into the territory of cultural theory.",
    literary:
      "Every poem opens a territory where language is allowed to wander.",
  },
  {
    id: "domain",
    label: "domain",
    meaning: "领地；管辖范围",
    definition:
      "a realm controlled by a person, organization, or system of thought",
    collocations: [
      "public domain",
      "digital territory",
      "domain of knowledge",
    ],
    synonyms: ["domain", "realm", "jurisdiction"],
    origin:
      "Territory and domain share the idea of control, ownership, and bounded space.",
    example:
      "The archive places the novel in the public domain.",
    news:
      "Technology companies now compete over the territory of personal data.",
    academic:
      "The question belongs to the territory of sociolinguistics.",
    literary:
      "Imagination claims its own territory beyond the reach of law.",
  },
];

const CONTEXT_ICONS = {
  news: Newspaper,
  academic: GraduationCap,
  literary: Quote,
} as const;

export function WordsExplorer({
  open,
  collectedIds,
  onClose,
  onCollect,
}: {
  open: boolean;
  collectedIds: string[];
  onClose: () => void;
  onCollect: (item: CollectedWord) => void;
}) {
  const [activeSenseId, setActiveSenseId] = useState(SENSES[0]!.id);
  const activeSense =
    SENSES.find((sense) => sense.id === activeSenseId) ?? SENSES[0]!;
  const collectedId = `word-${WORD.term}-${activeSense.id}`;
  const collected = collectedIds.includes(collectedId);

  return (
    <AnimatePresence>
      {open ? (
        <motion.section
          className="words-explorer"
          aria-label="Re Words vocabulary space"
          initial={{ opacity: 0, y: 26, scale: 0.98 }}
          animate={{ opacity: 1, y: 0, scale: 1 }}
          exit={{ opacity: 0, y: 18, scale: 0.985 }}
          transition={{ duration: 0.42, ease: [0.22, 1, 0.36, 1] }}
        >
          <header className="words-explorer__header">
            <button type="button" onClick={onClose}>
              <ArrowLeft size={16} />
              返回主空间
            </button>
            <span>
              <small>Re · Words</small>
              <strong>词汇探索空间</strong>
            </span>
            <em>Meaning grows through connections.</em>
          </header>

          <div className="words-explorer__body">
            <div className="words-explorer__map">
              <svg viewBox="0 0 640 430" aria-hidden="true">
                <path d="M310 215 C245 160 190 120 120 92" />
                <path d="M310 215 C240 258 180 312 112 350" />
                <path d="M330 215 C395 158 450 118 526 88" />
                <path d="M330 215 C400 260 460 312 534 352" />
              </svg>
              <div className="words-explorer__core">
                <small>{WORD.partOfSpeech}</small>
                <strong>{WORD.term}</strong>
                <span>{WORD.pronunciation}</span>
              </div>
              {SENSES.map((sense, index) => (
                <button
                  type="button"
                  key={sense.id}
                  className={cn(
                    "words-explorer__sense",
                    `words-explorer__sense--${index + 1}`,
                    activeSense.id === sense.id && "is-active",
                  )}
                  onClick={() => setActiveSenseId(sense.id)}
                >
                  <small>{String(index + 1).padStart(2, "0")}</small>
                  <strong>{sense.label}</strong>
                  <span>{sense.meaning}</span>
                </button>
              ))}
            </div>

            <aside className="words-explorer__detail">
              <div className="words-explorer__meaning">
                <span className="eyebrow">Selected meaning</span>
                <h2>{activeSense.label}</h2>
                <strong>{activeSense.meaning}</strong>
                <p>{activeSense.definition}</p>
              </div>

              <div className="words-explorer__word-grid">
                <section>
                  <small>Collocations</small>
                  <div>
                    {activeSense.collocations.map((item) => (
                      <span key={item}>{item}</span>
                    ))}
                  </div>
                </section>
                <section>
                  <small>Synonyms</small>
                  <div>
                    {activeSense.synonyms.map((item) => (
                      <span key={item}>{item}</span>
                    ))}
                  </div>
                </section>
              </div>

              <section className="words-explorer__origin">
                <small>Word origin</small>
                <p>{activeSense.origin}</p>
              </section>

              <blockquote>
                <Quote size={14} />
                {activeSense.example}
              </blockquote>

              <section className="words-explorer__contexts">
                {(
                  [
                    ["news", "News context", activeSense.news],
                    ["academic", "Academic context", activeSense.academic],
                    ["literary", "Literary context", activeSense.literary],
                  ] as const
                ).map(([kind, label, text]) => {
                  const Icon = CONTEXT_ICONS[kind];
                  return (
                    <article key={kind}>
                      <header>
                        <Icon size={13} />
                        <small>{label}</small>
                      </header>
                      <p>{text}</p>
                    </article>
                  );
                })}
              </section>

              <button
                type="button"
                className={cn(
                  "words-explorer__collect",
                  collected && "is-collected",
                )}
                disabled={collected}
                onClick={() =>
                  onCollect({
                    id: collectedId,
                    title: `${WORD.term} · ${activeSense.label}`,
                    meta: `${activeSense.meaning} · collected from Re / Words`,
                    kind: "save",
                  })
                }
              >
                {collected ? <Check size={15} /> : <BookmarkPlus size={15} />}
                {collected ? "已收藏到 Collection" : "收藏到 Collection"}
              </button>
            </aside>
          </div>
        </motion.section>
      ) : null}
    </AnimatePresence>
  );
}
