import { Trash2, X } from "lucide-react";
import { AnimatePresence, motion } from "motion/react";
import { PaperWad } from "../paper/PaperWad";
import "./discard-paper.css";

/**
 * 「揉掉一张纸」的确认层。
 *
 * 删东西不该是「啪」地一下消失 —— 那张纸先在手里被揉成一团
 * （PaperWad，自己画的那张），按了丢弃才真的没了。
 * 抽屉里的物件和单词本里的词卡都走这一层，所以纸面上的字由 spec 给。
 */

export interface DiscardPaperSpec {
  /** 换一张纸就换一个 key —— 同一个东西再删一次也重放一遍揉皱。 */
  key: string;
  /** 纸面上的眉题，比如「词汇积累 · Words」。 */
  kicker: string;
  title: string;
  meta: string;
  /** 纸的颜色；默认是米白，单词本用的是它自己那种偏绿的纸。 */
  paperColor?: string;
  /** 折痕的随机种子：同一个东西每次揉出来的褶皱是一样的。 */
  seed?: number;
}

function escapeXml(value: string) {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

/** 把「这张纸上写着什么」画成一张图，交给 PaperWad 去揉。 */
function createPaperSource(spec: DiscardPaperSpec) {
  const title = escapeXml(spec.title);
  const meta = escapeXml(spec.meta);
  const kicker = escapeXml(spec.kicker);
  const svg = `
    <svg xmlns="http://www.w3.org/2000/svg" width="520" height="680" viewBox="0 0 520 680">
      <rect width="520" height="680" rx="18" fill="#fbf7ef"/>
      <rect x="42" y="42" width="436" height="596" rx="10" fill="#fffdf8" stroke="#d8d0c5" stroke-width="2"/>
      <rect x="66" y="76" width="92" height="18" rx="9" fill="#c89a71"/>
      <text x="66" y="112" fill="#a49eae" font-family="'Helvetica Neue', Arial, sans-serif" font-size="13" letter-spacing="2">${kicker}</text>
      <text x="66" y="152" fill="#5f5b70" font-family="'Times New Roman', 'SimSun', '宋体', serif" font-size="30">${title}</text>
      <text x="66" y="188" fill="#948fa2" font-family="'Times New Roman', 'SimSun', '宋体', serif" font-size="17">${meta}</text>
      ${Array.from({ length: 12 }, (_, index) => `<rect x="66" y="${238 + index * 29}" width="${index % 3 === 0 ? 356 : 296}" height="4" rx="2" fill="#d8d2c8"/>`).join("")}
    </svg>
  `;
  return `data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}`;
}

export function DiscardPaper({
  spec,
  confirmLabel = "丢弃",
  onCancel,
  onConfirm,
}: {
  spec: DiscardPaperSpec | null;
  confirmLabel?: string;
  onCancel: () => void;
  onConfirm: () => void;
}) {
  return (
    <AnimatePresence>
      {spec ? (
        <motion.div
          className="discard-paper-layer"
          role="presentation"
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          onClick={onCancel}
        >
          <motion.section
            className="discard-paper"
            role="dialog"
            aria-modal="true"
            aria-label={`${confirmLabel} ${spec.title}`}
            initial={{ opacity: 0, y: 26, scale: 0.97 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: 18, scale: 0.98 }}
            transition={{ duration: 0.36, ease: [0.22, 1, 0.36, 1] }}
            onClick={(event) => event.stopPropagation()}
          >
            <header>
              <span>
                <small>{spec.kicker}</small>
                <strong>{spec.title}</strong>
                <em>{spec.meta}</em>
              </span>
              <button type="button" onClick={onCancel} aria-label="保留">
                <X size={15} />
              </button>
            </header>
            <div className="discard-paper__stage">
              <PaperWad
                key={spec.key}
                src={createPaperSource(spec)}
                alt={`${spec.title} 那张纸`}
                width={260}
                height={340}
                sceneHeight={390}
                tilt={-1.5}
                amount={0.92}
                crumpleTime={0.52}
                restoreTime={0.42}
                creaseCount={7}
                creaseDepth={0.82}
                creaseSharp={0.68}
                paperGrain={0.11}
                paperColor={spec.paperColor ?? "#f7f0e5"}
                stay
                draggable
                tiltLimit={12}
                driftLimit={120}
                seed={spec.seed ?? spec.title.length * 7 + spec.kicker.length * 13}
              />
            </div>
            <footer>
              <button type="button" onClick={onCancel}>
                保留
              </button>
              <button
                type="button"
                className="is-danger"
                onClick={onConfirm}
              >
                <Trash2 size={14} />
                {confirmLabel}
              </button>
            </footer>
          </motion.section>
        </motion.div>
      ) : null}
    </AnimatePresence>
  );
}

export default DiscardPaper;
