import type { DrawerNote } from "@leafia/shared";
import type { ReaderBook } from "../../lib/readerLibrary";
import {
  bookBaseId,
  currentLearningBooks,
  formatRelativeTime,
  practiceSummary,
  type StudyEvent,
} from "./studyLog";

export interface RecentLearningCard {
  id: string;
  src: string;
  alt: string;
  title: string;
  subtitle: string;
}

export interface RecentLearningLeaf {
  id: string;
  front: string;
  back: string;
  alt: string;
}

export interface ElasticBookItem {
  id: string;
  src: string;
  alt: string;
  title: string;
  subtitle: string;
  focus?: number;
}

/** 一天里的三条线：读书、弹琴、复习。 */
export interface StudyChartDay {
  id: string;
  /** 这一天的零点。 */
  at: number;
  label: string;
  reading: number;
  practice: number;
  review: number;
  total: number;
}

export interface StudyCharts {
  days: StudyChartDay[];
  /** 近两周有学习记录的天数。 */
  activeDays: number;
  /** 到今天为止连着学了几天。 */
  streak: number;
  /** 近两周一共多少次动作。 */
  total: number;
  /** 知识点/题目答对率，没有数据就是 null。 */
  accuracy: number | null;
  /** 词汇复习的通过率，没有数据就是 null。 */
  reviewPass: number | null;
}

const DAY_MS = 86_400_000;

function startOfDay(at: number) {
  const date = new Date(at);
  date.setHours(0, 0, 0, 0);
  return date.getTime();
}

function eventBucket(
  kind: StudyEvent["kind"],
): "reading" | "practice" | "review" {
  if (kind === "practice") return "practice";
  if (kind === "word-review" || kind === "knowledge-review") return "review";
  return "reading";
}

/**
 * 近两周的学习数据 —— 不是「学了什么」的清单，而是走势：
 * 每天三条线的高低、连着学了几天、练习与复习的成色。
 */
export function buildStudyCharts(
  events: StudyEvent[],
  days = 14,
  now = Date.now(),
): StudyCharts {
  const today = startOfDay(now);
  const buckets = new Map<number, StudyChartDay>();
  for (let offset = days - 1; offset >= 0; offset -= 1) {
    const at = today - offset * DAY_MS;
    const date = new Date(at);
    buckets.set(at, {
      id: `day-${at}`,
      at,
      label: `${date.getMonth() + 1}/${date.getDate()}`,
      reading: 0,
      practice: 0,
      review: 0,
      total: 0,
    });
  }

  const perDay = new Map<number, number>();
  let correct = 0;
  let answered = 0;
  let reviewed = 0;
  let passed = 0;

  for (const event of events) {
    const day = startOfDay(event.at);
    const bucket = buckets.get(day);
    if (bucket) {
      bucket[eventBucket(event.kind)] += 1;
      bucket.total += 1;
    }
    perDay.set(day, (perDay.get(day) ?? 0) + 1);
    if (event.kind === "knowledge-review") {
      answered += 1;
      if (event.correct) correct += 1;
    } else if (event.kind === "quiz-completed") {
      correct += event.correct;
      answered += event.total;
    } else if (event.kind === "word-review") {
      reviewed += event.reviewed;
      passed += event.passed;
    }
  }

  let streak = 0;
  for (let offset = 0; offset < days; offset += 1) {
    if (!perDay.has(today - offset * DAY_MS)) break;
    streak += 1;
  }

  const list = [...buckets.values()];
  return {
    days: list,
    activeDays: list.filter((entry) => entry.total > 0).length,
    streak,
    total: list.reduce((sum, entry) => sum + entry.total, 0),
    accuracy: answered > 0 ? Math.round((correct / answered) * 100) : null,
    reviewPass: reviewed > 0 ? Math.round((passed / reviewed) * 100) : null,
  };
}

function wrapText(
  context: CanvasRenderingContext2D,
  text: string,
  maxWidth: number,
  maxLines: number,
) {
  const words = text.split(/\s+/);
  const lines: string[] = [];
  let current = "";
  for (const word of words) {
    const candidate = current ? `${current} ${word}` : word;
    if (context.measureText(candidate).width <= maxWidth || !current) {
      current = candidate;
      continue;
    }
    lines.push(current);
    current = word;
    if (lines.length >= maxLines - 1) break;
  }
  if (current && lines.length < maxLines) lines.push(current);
  if (words.join(" ") !== lines.join(" ") && lines.length) {
    lines[lines.length - 1] = `${lines[lines.length - 1]!.replace(/[.,;:]?$/, "")}...`;
  }
  return lines;
}

export function createLearningImage(input: {
  kicker: string;
  title: string;
  detail: string;
  color: string;
  tone?: "front" | "back";
}) {
  if (typeof document === "undefined") return "";
  const canvas = document.createElement("canvas");
  canvas.width = 520;
  canvas.height = 740;
  const context = canvas.getContext("2d");
  if (!context) return "";

  const gradient = context.createLinearGradient(0, 0, 520, 740);
  gradient.addColorStop(0, input.tone === "back" ? "#241d2b" : input.color);
  gradient.addColorStop(1, input.tone === "back" ? "#51445d" : "#f4e9df");
  context.fillStyle = gradient;
  context.fillRect(0, 0, canvas.width, canvas.height);

  context.globalAlpha = 0.16;
  context.fillStyle = "#ffffff";
  context.beginPath();
  context.arc(405, 130, 108, 0, Math.PI * 2);
  context.fill();

  context.globalAlpha = 1;
  context.strokeStyle = "rgba(255,255,255,.38)";
  context.lineWidth = 1;
  for (let index = 0; index < 5; index += 1) {
    context.beginPath();
    context.moveTo(58, 470 + index * 30);
    context.lineTo(462, 450 + index * 30);
    context.stroke();
  }

  context.fillStyle =
    input.tone === "back" ? "rgba(255,255,255,.72)" : "rgba(255,255,255,.88)";
  context.font = "700 15px 'Times New Roman', 'SimSun', '宋体', serif";
  context.fillText(input.kicker.toUpperCase(), 48, 74);

  context.fillStyle = "#fff";
  context.font = "400 48px 'Times New Roman', 'SimSun', '宋体', serif";
  const lines = wrapText(context, input.title, 410, 3);
  lines.forEach((line, index) => {
    context.fillText(line, 48, 190 + index * 56);
  });

  context.fillStyle = "rgba(255,255,255,.78)";
  context.font = "17px 'Times New Roman', 'SimSun', '宋体', serif";
  wrapText(context, input.detail, 392, 5).forEach((line, index) => {
    context.fillText(line, 48, 430 + index * 28);
  });

  context.fillStyle = "rgba(255,255,255,.68)";
  context.font = "12px 'Times New Roman', 'SimSun', '宋体', serif";
  context.fillText("LEAFIA · RECENT LEARNING", 48, 690);

  return canvas.toDataURL("image/jpeg", 0.88);
}

function channels(hex: string) {
  const clean = hex.replace("#", "");
  const value = Number.parseInt(
    clean.length === 3
      ? clean.replace(/./g, (char) => `${char}${char}`)
      : clean,
    16,
  );
  if (!Number.isFinite(value)) return [120, 110, 100] as const;
  return [(value >> 16) & 255, (value >> 8) & 255, value & 255] as const;
}

/** 两种颜色拌在一起（t=0 取 a，t=1 取 b）。 */
function mixHex(a: string, b: string, t: number) {
  const one = channels(a);
  const two = channels(b);
  const blend = (x: number, y: number) => Math.round(x + (y - x) * t);
  return `rgb(${blend(one[0], two[0])}, ${blend(one[1], two[1])}, ${blend(one[2], two[2])})`;
}

/** 底色深就写浅字，底色浅就写深字 —— 和书脊上挑字色是一个意思。 */
function inkOn(hex: string) {
  const [r, g, b] = channels(hex);
  const luma = (0.299 * r + 0.587 * g + 0.114 * b) / 255;
  return luma > 0.6 ? "#3b2a1c" : "#f8f1e6";
}

/**
 * 一本书的立体像（「最近读到的」栏里那几张卡）。
 *
 * 以前这里给每本书发的都是同一张平面渐变色卡，书和书之间只剩下颜色
 * 的区别 —— 单词本在 3D 书架上是本立着的书，翻到记录里却成了一张纸片。
 * 这张画的是书本身：左边一条圆背书脊（五档受光 + 两道金线），右上露出
 * 一叠书口，封面上重排了书名（英文小字在上、中文大字在下，AI 画的图上
 * 那几个字糊，一律不用）。颜色取自这本书的书脊色，和书架上是同一支。
 */
export function createBookImage(input: {
  title: string;
  zhTitle?: string;
  color: string;
}) {
  if (typeof document === "undefined") return "";
  const canvas = document.createElement("canvas");
  canvas.width = 520;
  canvas.height = 740;
  const context = canvas.getContext("2d");
  if (!context) return "";

  const { color } = input;
  const ink = inkOn(color);

  // 底：书色洗淡成纸，右下角压一点点书色 —— 和原来那张卡一个调子。
  const wash = context.createLinearGradient(0, 0, 520, 740);
  wash.addColorStop(0, mixHex(color, "#ffffff", 0.9));
  wash.addColorStop(1, mixHex(color, "#f4e9df", 0.72));
  context.fillStyle = wash;
  context.fillRect(0, 0, 520, 740);

  context.globalAlpha = 0.14;
  context.fillStyle = "#ffffff";
  context.beginPath();
  context.arc(408, 128, 116, 0, Math.PI * 2);
  context.fill();
  context.globalAlpha = 1;

  // 书落在桌上：先一层散开的影子，再一层压实的。
  const bookLeft = 104;
  const bookRight = 428;
  const bookTop = 168;
  const bookBottom = 604;
  const spineWidth = 46;
  const shadow = context.createRadialGradient(266, 620, 30, 266, 620, 210);
  shadow.addColorStop(0, "rgba(52,36,24,.3)");
  shadow.addColorStop(1, "rgba(52,36,24,0)");
  context.fillStyle = shadow;
  context.beginPath();
  context.ellipse(266, 618, 208, 34, 0, 0, Math.PI * 2);
  context.fill();

  // 书口：右上一叠纸。顶面斜切一点，看着才是立起来的。
  context.fillStyle = "#f0e6d4";
  context.beginPath();
  context.moveTo(bookLeft + spineWidth, bookTop - 12);
  context.lineTo(bookRight + 16, bookTop - 12);
  context.lineTo(bookRight, bookTop + 2);
  context.lineTo(bookLeft + spineWidth, bookTop + 2);
  context.closePath();
  context.fill();
  context.fillStyle = "#e6dac4";
  context.beginPath();
  context.moveTo(bookRight, bookTop + 2);
  context.lineTo(bookRight + 16, bookTop - 12);
  context.lineTo(bookRight + 16, bookBottom - 12);
  context.lineTo(bookRight, bookBottom);
  context.closePath();
  context.fill();
  context.strokeStyle = "rgba(120,102,78,.35)";
  context.lineWidth = 1;
  for (let y = bookTop + 16; y < bookBottom - 10; y += 7) {
    context.beginPath();
    context.moveTo(bookRight + 1, y);
    context.lineTo(bookRight + 15, y - 13);
    context.stroke();
  }

  // 封面：布面底色，上浅下深，和书脊同一个色系但更沉一档。
  const cover = context.createLinearGradient(0, bookTop, 0, bookBottom);
  cover.addColorStop(0, mixHex(color, "#ffffff", 0.08));
  cover.addColorStop(0.55, color);
  cover.addColorStop(1, mixHex(color, "#2a1d12", 0.22));
  context.fillStyle = cover;
  context.fillRect(
    bookLeft + spineWidth,
    bookTop,
    bookRight - bookLeft - spineWidth,
    bookBottom - bookTop,
  );

  // 布纹：横竖各几道极淡的线，不做成方格纸。
  context.save();
  context.beginPath();
  context.rect(
    bookLeft + spineWidth,
    bookTop,
    bookRight - bookLeft - spineWidth,
    bookBottom - bookTop,
  );
  context.clip();
  context.strokeStyle = "rgba(255,255,255,.07)";
  for (let x = bookLeft + spineWidth; x < bookRight; x += 13) {
    context.beginPath();
    context.moveTo(x, bookTop);
    context.lineTo(x, bookBottom);
    context.stroke();
  }
  for (let y = bookTop; y < bookBottom; y += 13) {
    context.beginPath();
    context.moveTo(bookLeft + spineWidth, y);
    context.lineTo(bookRight, y);
    context.stroke();
  }
  context.restore();

  // 封面上的金线方框 + 书脊根部那道折沟。
  context.strokeStyle = "rgba(214,178,106,.6)";
  context.lineWidth = 1.4;
  context.strokeRect(bookLeft + spineWidth + 24, bookTop + 28, 200, 316);
  const hinge = context.createLinearGradient(bookLeft + spineWidth, 0, bookLeft + spineWidth + 26, 0);
  hinge.addColorStop(0, "rgba(20,12,6,.42)");
  hinge.addColorStop(1, "rgba(20,12,6,0)");
  context.fillStyle = hinge;
  context.fillRect(bookLeft + spineWidth, bookTop, 26, bookBottom - bookTop);

  // 书脊：五档受光，左边迎光、右边转进阴影 —— 书架上的书脊就是这个画法。
  const spineLeft = bookLeft;
  const spineRight = bookLeft + spineWidth;
  const spine = context.createLinearGradient(spineLeft, 0, spineRight, 0);
  spine.addColorStop(0, mixHex(color, "#ffffff", 0.34));
  spine.addColorStop(0.28, mixHex(color, "#ffffff", 0.14));
  spine.addColorStop(0.62, color);
  spine.addColorStop(1, mixHex(color, "#2a1d12", 0.3));
  context.fillStyle = spine;
  context.fillRect(spineLeft, bookTop, spineWidth, bookBottom - bookTop);

  context.fillStyle = "rgba(255,255,255,.34)";
  context.fillRect(spineLeft + 2, bookTop, 2, bookBottom - bookTop);

  // 书脊上的两道金线（书架上「能打开的书」都带一条金色标记）。
  context.fillStyle = "rgba(224,190,120,.85)";
  context.fillRect(spineLeft + 8, bookTop + 46, spineWidth - 16, 5);
  context.fillRect(spineLeft + 8, bookBottom - 58, spineWidth - 16, 5);

  // 书名：英文小字在上，中文大字在下，都在金线框里。
  const coverLeft = bookLeft + spineWidth + 24;
  const coverWidth = 200;
  context.fillStyle = ink;
  context.globalAlpha = 0.82;
  context.font = "600 13px 'Times New Roman', 'SimSun', '宋体', serif";
  wrapText(context, (input.title || "").toUpperCase(), coverWidth, 2).forEach(
    (line, index) => {
      context.fillText(line, coverLeft + 12, bookTop + 84 + index * 20);
    },
  );
  context.globalAlpha = 1;

  context.font = "700 30px 'Times New Roman', 'SimSun', '宋体', serif";
  const zh = input.zhTitle?.trim() || input.title || "书";
  wrapText(context, zh, coverWidth, 3).forEach((line, index) => {
    context.fillText(line, coverLeft + 12, bookTop + 190 + index * 40);
  });

  return canvas.toDataURL("image/jpeg", 0.9);
}

function findBook(books: ReaderBook[], id: string) {
  const base = bookBaseId(id);
  return books.find((book) => bookBaseId(String(book.id)) === base);
}

export function buildRecentLearning(
  events: StudyEvent[],
  notes: DrawerNote[],
  books: ReaderBook[],
) {
  const recentBooks = currentLearningBooks(events, 4);
  const practices = practiceSummary(events).slice(0, 2);
  const recentEvents = [...events].sort((a, b) => b.at - a.at).slice(0, 5);

  const cards: RecentLearningCard[] = recentBooks.map((record, index) => {
    const book = findBook(books, record.bookId);
    const title = book?.zhTitle || book?.title || record.bookId;
    const subtitle = record.lastTopic
      ? `最近学到：${record.lastTopic}`
      : `已打开 ${record.openCount} 次`;
    const color =
      book?.spine ?? ["#8d7cad", "#7795a0", "#b98576", "#7d906c"][index % 4]!;
    return {
      id: `learning-${record.bookId}`,
      // 在书架上找得到这本书，就画书本身 —— 立体的封面，颜色和架子上的
      // 那本同源（单词本在这条记录里也是那本带书脊的书，不再是张纸片）。
      // 找不到（记录比现存的书还旧）才退回原来那张平面卡。
      src: book
        ? createBookImage({ title: book.title, zhTitle: book.zhTitle, color })
        : createLearningImage({
            kicker: "Reading now",
            title,
            detail: subtitle,
            color,
          }),
      alt: `${title} 最近学习卡`,
      title,
      subtitle,
    };
  });

  for (const practice of practices) {
    cards.push({
      id: `practice-${practice.region}`,
      src: createLearningImage({
        kicker: "Piano practice",
        title: `练习分区 ${practice.region + 1}`,
        detail: `${practice.sessions} 次练习 · ${practice.keys} 个琴键`,
        color: "#76958e",
      }),
      alt: `练习分区 ${practice.region + 1}`,
      title: `练习分区 ${practice.region + 1}`,
      subtitle: `${practice.sessions} 次练习 · ${practice.keys} 个琴键`,
    });
  }

  if (!cards.length && notes.length) {
    for (const note of notes.slice(0, 4)) {
      cards.push({
        id: `note-${note.id}`,
        src: createLearningImage({
          kicker: "Saved note",
          title: note.title,
          detail: note.meta || "本机便条",
          color: "#a77c8d",
        }),
        alt: note.title,
        title: note.title,
        subtitle: note.meta || "本机便条",
      });
    }
  }

  const leaves: RecentLearningLeaf[] = recentEvents.map((event, index) => {
    const bookId = "bookId" in event ? event.bookId : null;
    const book = bookId ? findBook(books, bookId) : undefined;
    const title =
      event.kind === "practice"
        ? `练习分区 ${event.region + 1}`
        : event.kind === "word-review"
          ? "词汇复习"
          : event.kind === "card-created"
            ? "新建知识卡"
            : book?.zhTitle || book?.title || bookId || "学习记录";
    const detail =
      event.kind === "topic"
        ? `学习主题 · ${event.topic}`
        : event.kind === "practice"
          ? `${event.keys} 个琴键 · ${formatRelativeTime(event.at)}`
          : event.kind === "complete"
            ? `已标记完成 · ${formatRelativeTime(event.at)}`
            : event.kind === "resume"
              ? `恢复学习 · ${formatRelativeTime(event.at)}`
              : event.kind === "knowledge-review"
                ? `${event.correct ? "知识点答对" : "知识点需复习"} · ${formatRelativeTime(event.at)}`
                : event.kind === "quiz-completed"
                  ? `${event.correct}/${event.total} 正确 · ${formatRelativeTime(event.at)}`
                  : event.kind === "word-review"
                    ? `${event.passed}/${event.reviewed} 通过 · ${formatRelativeTime(event.at)}`
                    : event.kind === "card-created"
                      ? `知识卡已保存 · ${formatRelativeTime(event.at)}`
                      : `最近打开 · ${formatRelativeTime(event.at)}`;
    return {
      id: `event-${event.at}-${index}`,
      front: createLearningImage({
        kicker: "Recent learning",
        title,
        detail,
        color: book?.spine ?? "#806f91",
      }),
      back: createLearningImage({
        kicker: "Learning detail",
        title: detail,
        detail: "打开这一页，回到最近一次学习记录。",
        color: book?.spine ?? "#806f91",
        tone: "back",
      }),
      alt: `${title} 学习记录`,
    };
  });

  const uniqueBooks = new Map<string, ReaderBook>();
  books.forEach((book) => {
    const id = bookBaseId(String(book.id));
    if (!id.startsWith("core-") && !id.startsWith("shelf-")) return;
    if (!uniqueBooks.has(id)) uniqueBooks.set(id, book);
  });

  const elasticBooks: ElasticBookItem[] = [...uniqueBooks.values()].map(
    (book, index) => ({
      id: bookBaseId(String(book.id)),
      src: createLearningImage({
        kicker: "Book",
        title: book.zhTitle || book.title,
        detail: book.author,
        color:
          book.spine ??
          ["#71638f", "#688691", "#a97568", "#738368"][index % 4]!,
      }),
      alt: `${book.zhTitle || book.title} 封面`,
      title: book.zhTitle || book.title,
      subtitle: book.title,
      focus: 0.42 + (index % 3) * 0.08,
    }),
  );

  return { cards, leaves, books: elasticBooks };
}
