import {
  type KeyboardEvent,
  type PointerEvent as ReactPointerEvent,
  type ReactNode,
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
} from "react";
import { usePrefersReducedMotion } from "../../motion/usePrefersReducedMotion";
import "./card-panorama.css";

/**
 * 卡片盘的本体：中间一张正对镜头，后面的卡一层一层往斜后方退 —— 往右挪
 * 一点、往深里推一段、转过去几度；每退一层压暗一档、糊一点，再蒙上一层
 * 墨（墨的颜色由外面给，跟着皮肤走）。
 *
 * 这是自研的（这一格原来站的是 React Bits 的 DepthCarousel 照抄件，已换
 * 掉），观感和手感照旧：拖动带一点惯性，滚轮停下才归位，左右方向键翻，
 * 点后面的卡只是把它转到中间来。位置存在 ref 里逐帧写 style，不走 React
 * 渲染 —— 一次翻页几百毫秒，不是几百次重渲染。
 */

/** 每退一层：往右挪多少、往深里推多少、转过去多少度。 */
const SPREAD = 90;
const DEPTH = 220;
const TILT = 22;
/** 一层一层摆到第几层为止（正卡是 0）；再往后的直接不画。 */
const VISIBLE = 4.5;
/** 每退一层：暗多少、糊多少、墨多浓；亮度掉到地板以下就停住。 */
const DIM_STEP = 0.2;
const BLUR_MAX = 6;
const TINT_CAP = 0.86;
const DIM_FLOOR = 0.15;
/** 转一次的时长（毫秒），三次方缓出：起步快，最后几十毫秒几乎在滑。 */
const SLIDE_MS = 700;
/** 拖多远算一层；松手时把速度往后多看这么多毫秒。 */
const DRAG_RATIO = 0.55;
const DRAG_MIN_PX = 40;
const FLING_MS = 180;
/** 滚轮：一格滚多远算一层，停下多久归位（毫秒）。 */
const WHEEL_RATIO = 0.9;
const WHEEL_SETTLE_MS = 130;
/** 指针挪过这么多才算「拖起来了」，这时候才把指针收过来。 */
const DRAG_AFTER = 4;

const clamp = (value: number, min: number, max: number) =>
  Math.min(Math.max(value, min), max);

/** 把任意位置折进 [0, n) —— 盘是绕着圈排的，往哪边都能一直转。 */
const wrap = (value: number, count: number) => ((value % count) + count) % count;

export interface CardPanoramaItem {
  /** 卡面；纸色、阴影、里面的字都归调用方。 */
  content: ReactNode;
}

export interface CardPanoramaProps {
  items: CardPanoramaItem[];
  cardWidth?: number;
  cardHeight?: number;
  /** 卡自己的圆角（写在卡的行内样式上）。 */
  radius?: number;
  /** 退到后面压上去的那层墨的颜色，越靠后越浓。 */
  tint?: string;
  /** 读屏读到的名字。 */
  label?: string;
  /** 一开始停在第几张。之后换不跟着变（换一批卡时才重新折回范围）。 */
  initialIndex?: number;
  /** 停稳到某张上（拖完 / 滚完 / 点完 / 方向键）时喊一声。 */
  onChange?: (index: number) => void;
  className?: string;
}

/** 离正位 d 层的那张卡该是什么样（d 为正 = 排在后面）。 */
function placementOf(d: number) {
  const back = Math.max(0, d);
  return {
    x: SPREAD * d,
    z: -DEPTH * d,
    /* 只有紧挨正卡的那一层在转，再往后都停在同一个角度上。 */
    tilt: TILT * clamp(d, 0, 1),
    /* 转到前面去的那几张（d < 0）：下一层就淡没了，别一屁股压在正卡上。 */
    fade: d < 0 ? Math.max(0, 1 + d) : 1,
    dim: Math.max(DIM_FLOOR, 1 - back * DIM_STEP),
    blur: Math.min(BLUR_MAX, (back / 4) * BLUR_MAX),
    tint: clamp(back * DIM_STEP * 1.25, 0, TINT_CAP),
    /* 远远退出去的就不画了，省下合成几十层模糊卡的钱。 */
    drawn: Math.abs(d) <= VISIBLE,
  };
}

export function CardPanorama({
  items,
  cardWidth = 208,
  cardHeight = 264,
  radius = 14,
  tint = "#2f3a35",
  label = "卡片盘",
  initialIndex = 0,
  onChange,
  className,
}: CardPanoramaProps) {
  const count = items.length;
  const prefersReducedMotion = usePrefersReducedMotion();

  const rootRef = useRef<HTMLDivElement | null>(null);
  const cardRefs = useRef<Array<HTMLDivElement | null>>([]);
  const tintRefs = useRef<Array<HTMLSpanElement | null>>([]);
  /** 盘现在停在哪儿（小数 = 正停在两张中间）。 */
  const posRef = useRef(initialIndex);
  /** 眼下的正卡是哪张（换了才通知外面）。 */
  const frontRef = useRef(initialIndex);
  const [front, setFront] = useState(initialIndex);
  /** 整盘收到格子里放得下的比例（格子窄了整盘缩一缩）。 */
  const scaleRef = useRef(1);

  const glideRef = useRef(0);
  const wheelTimerRef = useRef(0);
  const dragRef = useRef<{
    pointerId: number;
    startX: number;
    startPos: number;
    lastX: number;
    lastT: number;
    velocity: number;
    moved: boolean;
  } | null>(null);
  /** 刚拖完的那一下 click 不算数（松手正好落在卡上时）。 */
  const draggedRef = useRef(false);

  const onChangeRef = useRef(onChange);
  const reducedRef = useRef(prefersReducedMotion);
  const layoutRef = useRef({ count, cardWidth });
  onChangeRef.current = onChange;
  reducedRef.current = prefersReducedMotion;
  layoutRef.current = { count, cardWidth };

  /** 拖一层的像素宽 —— 盘缩了，手感也要跟着缩。 */
  const stepPx = useCallback(
    () => Math.max(layoutRef.current.cardWidth * DRAG_RATIO * scaleRef.current, DRAG_MIN_PX),
    [],
  );

  /** 把「现在停在 pos」画到每一张卡上（不经过 React）。 */
  const paint = useCallback((pos: number) => {
    const { count: total } = layoutRef.current;
    if (!total) return;
    const scale = scaleRef.current;
    for (let i = 0; i < total; i += 1) {
      const element = cardRefs.current[i];
      if (!element) continue;
      /* 离正位几层（就近绕，别为了到隔壁绕一整圈）。 */
      let d = i - pos;
      d = ((d % total) + total) % total;
      if (d > total / 2) d -= total;

      const spot = placementOf(d);
      element.style.transform = `translate(-50%, -50%) scale(${scale.toFixed(4)}) translateX(${spot.x.toFixed(2)}px) translateZ(${spot.z.toFixed(2)}px) rotateY(${spot.tilt.toFixed(2)}deg)`;
      element.style.opacity = (spot.drawn ? spot.fade : 0).toFixed(3);
      element.style.filter = `brightness(${spot.dim.toFixed(3)}) blur(${spot.blur.toFixed(2)}px)`;
      element.style.zIndex = String(Math.round(2000 - d * 20));
      element.style.pointerEvents = spot.drawn && spot.fade > 0.05 ? "auto" : "none";

      const shade = tintRefs.current[i];
      if (shade) shade.style.opacity = spot.tint.toFixed(3);
    }
  }, []);

  /** 从脚下走到 target 去；animate=false（或用户关了动效）就一步到位。 */
  const glideTo = useCallback(
    (target: number, animate: boolean) => {
      cancelAnimationFrame(glideRef.current);
      glideRef.current = 0;
      const from = posRef.current;
      const duration = animate && !reducedRef.current ? SLIDE_MS : 0;
      const total = layoutRef.current.count;
      if (duration === 0 || Math.abs(target - from) < 0.001) {
        posRef.current = total ? wrap(target, total) : target;
        paint(posRef.current);
        return;
      }
      const startedAt = performance.now();
      const frame = (now: number) => {
        const t = Math.min(1, (now - startedAt) / duration);
        const eased = 1 - (1 - t) ** 3;
        posRef.current = from + (target - from) * eased;
        paint(posRef.current);
        if (t < 1) {
          glideRef.current = requestAnimationFrame(frame);
        } else {
          glideRef.current = 0;
          if (total) posRef.current = wrap(target, total);
        }
      };
      glideRef.current = requestAnimationFrame(frame);
    },
    [paint],
  );

  /** 把某张卡请到中间（点它、按方向键、拖完归位都走这儿）。 */
  const focusTo = useCallback(
    (index: number, animate: boolean) => {
      const total = layoutRef.current.count;
      if (total < 1) return;
      const target = wrap(Math.round(index), total);
      /* 就近走：差值折进 [-n/2, n/2)，免得从 0 退着走到最后一张。 */
      let delta = target - posRef.current;
      delta = ((delta % total) + total) % total;
      if (delta > total / 2) delta -= total;
      glideTo(posRef.current + delta, animate);
      if (target !== frontRef.current) {
        frontRef.current = target;
        setFront(target);
        onChangeRef.current?.(target);
      }
    },
    [glideTo],
  );

  const nudge = useCallback((step: number) => focusTo(frontRef.current + step, true), [focusTo]);

  /* 卡换了一批（加词、删词、换皮肤）：位置和正卡折回合法范围。 */
  useLayoutEffect(() => {
    if (!count) return;
    posRef.current = wrap(posRef.current, count);
    const nextFront = wrap(frontRef.current, count);
    if (nextFront !== frontRef.current) {
      frontRef.current = nextFront;
      setFront(nextFront);
    }
    paint(posRef.current);
  }, [count, paint]);

  /* 格子变宽变窄：整盘缩放，让最边上那层卡也待在格子里。 */
  useEffect(() => {
    const root = rootRef.current;
    if (!root) return undefined;
    const observer = new ResizeObserver((entries) => {
      const width = entries[0]?.contentRect.width ?? 0;
      const needed = cardWidth + SPREAD * 2 + 120;
      scaleRef.current = clamp(width / needed, 0.4, 1);
      paint(posRef.current);
    });
    observer.observe(root);
    return () => observer.disconnect();
  }, [cardWidth, paint]);

  /* 滚轮：先跟着滚，停 130ms 没人再滚，就归到最近那张上。 */
  useEffect(() => {
    const root = rootRef.current;
    if (!root) return undefined;
    const onWheel = (event: WheelEvent) => {
      if (layoutRef.current.count < 2) return;
      event.preventDefault();
      cancelAnimationFrame(glideRef.current);
      glideRef.current = 0;
      /* 横滚竖滚都认；按行滚的浏览器一滚一大格，先折算回像素。 */
      const raw =
        Math.abs(event.deltaX) > Math.abs(event.deltaY) ? event.deltaX : event.deltaY;
      const pixels = event.deltaMode === 1 ? raw * 24 : raw;
      posRef.current += clamp(pixels / (layoutRef.current.cardWidth * WHEEL_RATIO), -0.6, 0.6);
      paint(posRef.current);
      window.clearTimeout(wheelTimerRef.current);
      wheelTimerRef.current = window.setTimeout(
        () => focusTo(Math.round(posRef.current), true),
        WHEEL_SETTLE_MS,
      );
    };
    root.addEventListener("wheel", onWheel, { passive: false });
    return () => {
      root.removeEventListener("wheel", onWheel);
      window.clearTimeout(wheelTimerRef.current);
    };
  }, [focusTo, paint]);

  const handlePointerDown = useCallback((event: ReactPointerEvent<HTMLDivElement>) => {
    if (layoutRef.current.count < 2 || event.button !== 0) return;
    cancelAnimationFrame(glideRef.current);
    glideRef.current = 0;
    window.clearTimeout(wheelTimerRef.current);
    draggedRef.current = false;
    dragRef.current = {
      pointerId: event.pointerId,
      startX: event.clientX,
      startPos: posRef.current,
      lastX: event.clientX,
      lastT: performance.now(),
      velocity: 0,
      moved: false,
    };
  }, []);

  const handlePointerMove = useCallback(
    (event: ReactPointerEvent<HTMLDivElement>) => {
      const drag = dragRef.current;
      if (!drag || drag.pointerId !== event.pointerId) return;
      const dx = event.clientX - drag.startX;
      if (!drag.moved) {
        if (Math.abs(dx) < DRAG_AFTER) return;
        drag.moved = true;
        rootRef.current?.setPointerCapture(event.pointerId);
      }
      /* 这会儿手有多快 —— 松手时让它多滑一小段。 */
      const now = performance.now();
      const since = Math.max(now - drag.lastT, 1);
      drag.velocity = (event.clientX - drag.lastX) / since;
      drag.lastX = event.clientX;
      drag.lastT = now;
      posRef.current = drag.startPos - dx / stepPx();
      paint(posRef.current);
    },
    [paint, stepPx],
  );

  const handlePointerEnd = useCallback(
    (event: ReactPointerEvent<HTMLDivElement>) => {
      const drag = dragRef.current;
      if (!drag || drag.pointerId !== event.pointerId) return;
      dragRef.current = null;
      if (!drag.moved) return;
      draggedRef.current = true;
      /* 把松手那一下的速度往后多看一小段，再归到最近那张。 */
      const projected = posRef.current - (drag.velocity * FLING_MS) / stepPx();
      focusTo(Math.round(projected), true);
    },
    [focusTo, stepPx],
  );

  const handleKeyDown = useCallback(
    (event: KeyboardEvent<HTMLDivElement>) => {
      if (event.key === "ArrowLeft") {
        event.preventDefault();
        nudge(-1);
      } else if (event.key === "ArrowRight") {
        event.preventDefault();
        nudge(1);
      }
    },
    [nudge],
  );

  const handleCardClick = useCallback(
    (index: number) => {
      if (draggedRef.current) {
        draggedRef.current = false;
        return;
      }
      focusTo(index, true);
    },
    [focusTo],
  );

  useEffect(
    () => () => {
      cancelAnimationFrame(glideRef.current);
      window.clearTimeout(wheelTimerRef.current);
    },
    [],
  );

  if (!count) return null;

  return (
    <div
      ref={rootRef}
      className={["card-panorama", className].filter(Boolean).join(" ")}
      role="group"
      aria-roledescription="carousel"
      aria-label={label}
      tabIndex={0}
      onPointerDown={handlePointerDown}
      onPointerMove={handlePointerMove}
      onPointerUp={handlePointerEnd}
      onPointerCancel={handlePointerEnd}
      onKeyDown={handleKeyDown}
    >
      <div className="card-panorama__stage">
        {items.map((item, index) => (
          <div
            key={index}
            ref={(element) => {
              cardRefs.current[index] = element;
            }}
            className="card-panorama__card"
            style={{ width: cardWidth, height: cardHeight, borderRadius: radius }}
            aria-roledescription="slide"
            aria-label={`${index + 1} / ${count}`}
            aria-hidden={front !== index}
            data-front={front === index ? "true" : undefined}
            onClick={() => handleCardClick(index)}
          >
            <div className="card-panorama__content">{item.content}</div>
            <span
              className="card-panorama__tint"
              aria-hidden="true"
              ref={(element) => {
                tintRefs.current[index] = element;
              }}
              style={{ background: tint }}
            />
          </div>
        ))}
      </div>
    </div>
  );
}

export default CardPanorama;
