import {
  type CSSProperties,
  type KeyboardEvent,
  type PointerEvent,
  useCallback,
  useEffect,
  useRef,
  useState,
} from "react";
import { usePrefersReducedMotion } from "../../motion/usePrefersReducedMotion";
import "./leaf-flip.css";

export interface FlipLeaf {
  id?: string;
  /** 正面图（进来的那一面）。 */
  front: string;
  /** 背面图。 */
  back: string;
  /** 读屏用的说法，比如「知识语言学 学习记录」。 */
  alt?: string;
}

export interface LeafFlipProps {
  leaves: FlipLeaf[];
  /** 不传就照 CSS 变量 / 内定尺寸走。 */
  width?: number;
  height?: number;
  className?: string;
  emptyLabel?: string;
}

/** 背后露出几张（再往里看不见了，不渲染）。 */
const STACK = 3;
/** 每往后退一层：往右上错开多少、斜多少。 */
const STEP_X = 9;
const STEP_Y = -6;
const STEP_TILT = 2.4;
/** 拖多远算翻一页。 */
const DRAG_THRESHOLD = 46;
/** 挪过这么多才算真拖起来了，这时候才把指针收过来。 */
const CAPTURE_AFTER = 6;

const clamp = (value: number, min: number, max: number) =>
  Math.min(Math.max(value, min), max);

/**
 * 一叠纸页：当前这页摆在最上面，后面几页错着角露出来一点。
 * 点一下把最上面这页翻到背面，再点翻回来；拖一下或按方向键翻下一张。
 *
 * 翻面就交给 CSS 的 rotateY + backface-visibility，翻页只改当前索引；
 * 拖动过程只记位移，松手才决定翻不翻，免得和过渡打架。
 */
export function LeafFlip({
  leaves,
  width,
  height,
  className,
  emptyLabel = "还没有可翻的记录。",
}: LeafFlipProps) {
  const prefersReducedMotion = usePrefersReducedMotion();
  const dragRef = useRef<{
    pointerId: number;
    startX: number;
    captured: boolean;
  } | null>(null);
  // 拖完那一下松手时也会落在页面上，别让 click 再翻一次面。
  const draggedRef = useRef(false);
  const last = Math.max(leaves.length - 1, 0);
  const [index, setIndex] = useState(0);
  const [flipped, setFlipped] = useState(false);

  // 换了一叠纸（记录增删）就回到合法位置，并且从正面看起。
  useEffect(() => {
    setIndex((current) => clamp(current, 0, last));
  }, [last]);
  useEffect(() => {
    setFlipped(false);
  }, [index]);

  const step = useCallback(
    (delta: number) => setIndex((current) => clamp(current + delta, 0, last)),
    [last],
  );

  const handlePointerDown = useCallback((event: PointerEvent<HTMLDivElement>) => {
    if (event.button !== 0) return;
    draggedRef.current = false;
    dragRef.current = {
      pointerId: event.pointerId,
      startX: event.clientX,
      captured: false,
    };
  }, []);

  /** 真挪起来了才收指针：一按下就收，松手那下 click 会被投给盘子，页面自己收不到。 */
  const handlePointerMove = useCallback((event: PointerEvent<HTMLDivElement>) => {
    const drag = dragRef.current;
    if (!drag || drag.pointerId !== event.pointerId || drag.captured) return;
    if (Math.abs(event.clientX - drag.startX) < CAPTURE_AFTER) return;
    drag.captured = true;
    event.currentTarget.setPointerCapture?.(event.pointerId);
  }, []);

  const handlePointerUp = useCallback(
    (event: PointerEvent<HTMLDivElement>) => {
      const drag = dragRef.current;
      dragRef.current = null;
      if (!drag || drag.pointerId !== event.pointerId) return;
      const dx = event.clientX - drag.startX;
      if (Math.abs(dx) < DRAG_THRESHOLD) return;
      draggedRef.current = true;
      // 往左拖 = 翻下一张。
      step(dx < 0 ? 1 : -1);
    },
    [step],
  );

  const handleKeyDown = useCallback(
    (event: KeyboardEvent<HTMLDivElement>) => {
      if (event.key === "ArrowRight" || event.key === "ArrowDown") {
        event.preventDefault();
        step(1);
        return;
      }
      if (event.key === "ArrowLeft" || event.key === "ArrowUp") {
        event.preventDefault();
        step(-1);
        return;
      }
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        setFlipped((current) => !current);
      }
    },
    [step],
  );

  if (leaves.length === 0) {
    return (
      <div className={["leaf-flip", "leaf-flip--empty", className].filter(Boolean).join(" ")}>
        <p className="leaf-flip__empty">{emptyLabel}</p>
      </div>
    );
  }

  const leaf = leaves[index]!;
  const sizeStyle = {
    ...(width ? { "--flip-leaf-w": `${width}px` } : {}),
    ...(height ? { "--flip-leaf-h": `${height}px` } : {}),
  } as CSSProperties;

  return (
    <div className={["leaf-flip", className].filter(Boolean).join(" ")}>
      <div
        className={[
          "leaf-flip__stage",
          prefersReducedMotion && "is-static",
        ]
          .filter(Boolean)
          .join(" ")}
        style={sizeStyle}
        role="group"
        aria-label={`学习记录卡片，第 ${index + 1} 张，共 ${leaves.length} 张`}
        tabIndex={0}
        onKeyDown={handleKeyDown}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerCancel={() => {
          dragRef.current = null;
        }}
      >
        {leaves.map((entry, position) => {
          const offset = position - index;
          if (offset < 0 || offset > STACK) return null;
          const isTop = offset === 0;
          const pileStyle = {
            transform: `translate3d(${offset * STEP_X}px, ${offset * STEP_Y}px, 0) rotate(${offset * STEP_TILT}deg)`,
            zIndex: STACK + 1 - offset,
          } as CSSProperties;

          if (!isTop) {
            return (
              <span
                key={entry.id ?? position}
                className="leaf-flip__under"
                style={pileStyle}
                aria-hidden="true"
              />
            );
          }

          return (
            <div
              key={entry.id ?? position}
              className="leaf-flip__slot"
              style={pileStyle}
            >
              <button
                type="button"
                className={["leaf-flip__leaf", flipped && "is-flipped"]
                  .filter(Boolean)
                  .join(" ")}
                aria-pressed={flipped}
                aria-label={`${entry.alt ?? "学习记录"}，${flipped ? "背面" : "正面"}`}
                onClick={() => {
                  if (draggedRef.current) {
                    draggedRef.current = false;
                    return;
                  }
                  setFlipped((current) => !current);
                }}
              >
                <span className="leaf-flip__face is-front">
                  <img src={entry.front} alt="" draggable={false} />
                </span>
                <span className="leaf-flip__face is-back">
                  <img src={entry.back} alt="" draggable={false} />
                </span>
              </button>
            </div>
          );
        })}
      </div>

      <div className="leaf-flip__bar">
        <button
          type="button"
          className="leaf-flip__step"
          aria-label="上一张"
          disabled={index === 0}
          onClick={() => step(-1)}
        >
          ‹
        </button>
        <span className="leaf-flip__count" aria-hidden="true">
          {index + 1} / {leaves.length}
        </span>
        <button
          type="button"
          className="leaf-flip__step"
          aria-label="下一张"
          disabled={index === last}
          onClick={() => step(1)}
        >
          ›
        </button>
      </div>
    </div>
  );
}

export default LeafFlip;
