export interface PianoNote {
  label: (typeof PIANO_NOTES)[number]["label"];
  zh: (typeof PIANO_NOTES)[number]["zh"];
  skill: (typeof PIANO_NOTES)[number]["skill"];
  nameZh: (typeof PIANO_NOTES)[number]["nameZh"];
  detail: (typeof PIANO_NOTES)[number]["detail"];
  path: (typeof PIANO_NOTES)[number]["path"];
  hue: (typeof PIANO_NOTES)[number]["hue"];
  noteIndex: number;
  octave: number;
  midi: number;
  frequency: number;
}

export function pianoNoteForKey(index: number): PianoNote {
  const safeIndex = Math.max(0, Math.floor(index));
  const noteIndex = practiceRegionForKey(safeIndex);
  const note = PIANO_NOTES[noteIndex] ?? PIANO_NOTES[0];
  const midi = 48 + safeIndex;
  const octave = Math.floor(midi / 12) - 1;

  return {
    ...note,
    noteIndex,
    octave,
    midi,
    frequency: 440 * 2 ** ((midi - 69) / 12),
  };
}

export function practiceRegionForKey(index: number): number {
  const safeIndex = Math.min(
    PIANO_KEY_COUNT - 1,
    Math.max(0, Math.floor(index)),
  );
  return Math.min(
    PIANO_NOTES.length - 1,
    Math.floor((safeIndex * PIANO_NOTES.length) / PIANO_KEY_COUNT),
  );
}

export function firstKeyForPracticeRegion(region: number): number {
  const safeRegion = Math.min(
    PIANO_NOTES.length - 1,
    Math.max(0, Math.floor(region)),
  );
  return Math.ceil((safeRegion * PIANO_KEY_COUNT) / PIANO_NOTES.length);
}
