import {
  ArrowLeft,
  BookmarkPlus,
  Check,
  Eye,
  Search,
  Sparkles,
} from "lucide-react";
import { AnimatePresence, motion } from "motion/react";
import { useState } from "react";
import { cn } from "../../lib/cn";
import { DETECTIVE_WORDS, type DetectiveWord } from "./languageLabData";
import type { CollectedWord } from "./WordsExplorer";

export function PhonologyDetective({
  savedIds,
  onBack,
  onSave,
  onDiscovery,
}: {
  savedIds: string[];
  onBack: () => void;
  onSave: (item: CollectedWord) => void;
  onDiscovery: (id: string, title: string) => void;
}) {
  const [observed, setObserved] = useState<string[]>([]);
  const [selectedWord, setSelectedWord] = useState<DetectiveWord | null>(null);
  const [hypothesis, setHypothesis] = useState<"different" | "same" | null>(
    null,
  );
  const [stage, setStage] = useState<1 | 2 | 3>(1);
  const discoveryId = "language-discovery-allophone";
  const discovered = savedIds.includes(discoveryId);

  const observeWord = (word: DetectiveWord) => {
    setSelectedWord(word);
    setObserved((current) =>
      current.includes(word.word) ? current : [...current, word.word],
    );
  };

  const chooseHypothesis = (choice: "different" | "same") => {
    setHypothesis(choice);
    if (choice === "same") {
      setStage(3);
      onDiscovery(discoveryId, "Phoneme discovered");
    }
  };

  return (
    <motion.div
      className="phonology-detective"
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: -8 }}
    >
      <header className="language-lab__subheader">
        <button type="button" onClick={onBack}>
          <ArrowLeft size={15} />
          Sound Lab
        </button>
        <div>
          <span className="eyebrow">Observe · Infer · Unlock</span>
          <h2>Phonology Detective</h2>
        </div>
        <span>Case file: /l/</span>
      </header>

      <div className="phonology-detective__steps" aria-label="Detective progress">
        {[
          [1, "Observe"],
          [2, "Infer"],
          [3, "Unlock"],
        ].map(([step, label]) => (
          <span
            key={label}
            className={cn(
              stage >= Number(step) && "is-active",
              stage === Number(step) && "is-current",
            )}
          >
            {stage > Number(step) ? <Check size={11} /> : step}
            {label}
          </span>
        ))}
      </div>

      <AnimatePresence mode="wait">
        {stage === 1 ? (
          <motion.div
            key="observe"
            className="detective-stage detective-stage--observe"
            initial={{ opacity: 0, y: 12 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -8 }}
          >
            <div className="detective-stage__copy">
              <span className="eyebrow">Step 1 · Observe</span>
              <h3>同一个 /l/，为什么写出来不一样？</h3>
              <p>点击每一个词，收集它们在真实语音环境里的线索。</p>
            </div>
            <div className="detective-words">
              {DETECTIVE_WORDS.map((item, index) => (
                <motion.button
                  type="button"
                  key={item.word}
                  initial={{ opacity: 0, y: 14 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: index * 0.05 }}
                  className={cn(
                    observed.includes(item.word) && "is-observed",
                  )}
                  onClick={() => observeWord(item)}
                >
                  <small>{item.transcription}</small>
                  <strong>{item.word}</strong>
                  <span>{item.allophone}</span>
                  {observed.includes(item.word) ? <Eye size={12} /> : null}
                </motion.button>
              ))}
            </div>
            <aside>
              {selectedWord ? (
                <>
                  <small>Clue collected</small>
                  <strong>
                    {selectedWord.word} {selectedWord.transcription}
                  </strong>
                  <p>{selectedWord.clue}</p>
                </>
              ) : (
                <>
                  <Search size={18} />
                  <p>先观察四个词，不要急着看答案。</p>
                </>
              )}
            </aside>
            <button
              type="button"
              className="detective-primary"
              disabled={observed.length < DETECTIVE_WORDS.length}
              onClick={() => setStage(2)}
            >
              收集完成，开始推理
            </button>
          </motion.div>
        ) : stage === 2 ? (
          <motion.div
            key="infer"
            className="detective-stage detective-stage--infer"
            initial={{ opacity: 0, y: 12 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -8 }}
          >
            <span className="eyebrow">Step 2 · Infer</span>
            <h3>这些不同形式代表多个音位，还是同一个音位？</h3>
            <p>
              四个词都围绕 /l/。请根据位置和相邻声音判断，而不是只看符号。
            </p>
            <div>
              <button
                type="button"
                className={hypothesis === "different" ? "is-wrong" : ""}
                onClick={() => chooseHypothesis("different")}
              >
                它们是不同的音位
              </button>
              <button
                type="button"
                className={hypothesis === "same" ? "is-correct" : ""}
                onClick={() => chooseHypothesis("same")}
              >
                它们是同一个音位的不同形式
              </button>
            </div>
            {hypothesis === "different" ? (
              <small className="detective-feedback">
                再观察一次：这些词里的声音是否会造成意义对立？
              </small>
            ) : null}
          </motion.div>
        ) : (
          <motion.div
            key="unlock"
            className="detective-stage detective-stage--unlock"
            initial={{ opacity: 0, scale: 0.98 }}
            animate={{ opacity: 1, scale: 1 }}
          >
            <div className="detective-unlock">
              <Sparkles size={20} />
              <span className="eyebrow">Discovery unlocked</span>
              <h3>✓ Phoneme discovered</h3>
              <p>
                同一个音位 /l/ 在不同语音环境中，可以表现为不同的具体语音形式。
              </p>
            </div>
            <div className="detective-concepts">
              <article>
                <small>Phone</small>
                <strong>具体语音单位</strong>
                <p>实际发出的一个语音片段，例如观察到的 [l]、[ɫ] 或 [l̪]。</p>
              </article>
              <article>
                <small>Phoneme</small>
                <strong>抽象音位单位</strong>
                <p>语言中能够区分意义的声音单位，例如 /l/。</p>
              </article>
              <article>
                <small>Allophone</small>
                <strong>音位变体</strong>
                <p>同一音位在不同环境中的具体表现。</p>
              </article>
            </div>
            <button
              type="button"
              className={cn(
                "language-lab__save",
                discovered && "is-saved",
              )}
              disabled={discovered}
              onClick={() =>
                onSave({
                  id: discoveryId,
                  title: "Phoneme · Phone · Allophone",
                  meta: "Language Lab · Phonology discovery",
                  kind: "save",
                })
              }
            >
              {discovered ? <Check size={14} /> : <BookmarkPlus size={14} />}
              {discovered ? "Saved to Collection" : "Save discovery"}
            </button>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.div>
  );
}
