import {
  type CSSProperties,
  type KeyboardEvent,
  type MouseEvent,
  useCallback,
  useMemo,
  useRef,
} from "react";
import CardPanorama from "./CardPanorama";
import "./depth-card-rail.css";

export interface DepthRailCard {
  id: string;
  /** 卡面主词。有图时只留给读屏。 */
  word: string;
  /** 一两个字的标记，比如词性或来源。 */
  tag?: string;
  /** 词性等小签压在释义前面（卡面顶部就不再单独出一行小签）。 */
  tagBeforeMeaning?: boolean;
  /** 音标小字：跟在词下面、释义上面（词汇积累的卡用）。 */
  phonetic?: string;
  /** 释义或用例，一到两行。 */
  meaning?: string;
  /** 已复习轮次，卡脚小字。 */
  rounds?: number;
  /** 有图就铺满卡面，文字不再叠加。 */
  image?: string;
  /** 主题色相 0..360；不传按 id 推一个稳定的。 */
  hue?: number;
  /** 卡面底色；不传按色相算。 */
  tint?: string;
  /** 卡脚色带颜色。 */
  deep?: string;
  /** 卡脚的三格小样。 */
  swatch?: string[];
}

export interface DepthCardRailProps {
  items: DepthRailCard[];
  onSelect?: (item: DepthRailCard) => void;
  className?: string;
  emptyLabel?: string;
  /** 盘子下方那行操作提示。 */
  hint?: string;
  /** 打开时停在第几张。 */
  initialIndex?: number;
  cardWidth?: number;
  cardHeight?: number;
}

const DEFAULT_WIDTH = 208;
const DEFAULT_HEIGHT = 264;

/** 由 id 推一个稳定的 0..1 数，让同一张卡每次都是同一个色相。 */
function stableRatio(id: string, salt: number) {
  let hash = 2166136261 ^ salt;
  for (let i = 0; i < id.length; i += 1) {
    hash = Math.imul(hash ^ id.charCodeAt(i), 16777619);
  }
  hash ^= hash >>> 15;
  return ((hash >>> 0) % 100000) / 100000;
}

/** 没显式给颜色时，按色相算一套纸色 / 色带色。 */
function paletteFor(card: DepthRailCard) {
  const hue = card.hue ?? Math.round(stableRatio(card.id, 7) * 360);
  return {
    tint: card.tint ?? `hsl(${hue} 42% 94%)`,
    deep: card.deep ?? `hsl(${hue} 38% 62%)`,
  };
}

/**
 * 卡盘：中间一张正对镜头，后面的卡一层层往斜后方退、转过去、蒙上墨色。
 * 拖动或滚轮转盘，点中间那张打开。
 *
 * 转盘本体是同目录下自研的 CardPanorama（原来那版是 React Bits 的
 * DepthCarousel 照抄件，已换掉），这里只做两件 Leafia 的事：把卡面换成
 * 网页里的字卡（纸张、字、色带，不是图片），以及「点正对着的那张 = 打开它」
 * ——本体点哪张都只是把它转到中间来。
 */
export function DepthCardRail({
  items,
  onSelect,
  className,
  emptyLabel = "这里还没有卡片。",
  hint = "拖动 / 滚轮翻页 · 点中间那张打开",
  initialIndex = 0,
  cardWidth = DEFAULT_WIDTH,
  cardHeight = DEFAULT_HEIGHT,
}: DepthCardRailProps) {
  /** 转盘现在停在哪儿；点卡时要用它取回那张的原件。 */
  const activeRef = useRef(initialIndex);

  const data = useMemo(
    () =>
      items.map((card) => {
        const { tint, deep } = paletteFor(card);
        const sheetStyle = { "--deck-tint": tint, "--deck-deep": deep } as CSSProperties;
        return {
          content: (
            <div className="depth-card-rail__sheet" style={sheetStyle}>
              <span className="depth-card-rail__edge" aria-hidden="true" />
              {card.swatch?.length ? (
                <span className="depth-card-rail__swatch" aria-hidden="true">
                  {card.swatch.map((color, index) => (
                    <i key={index} style={{ background: color }} />
                  ))}
                </span>
              ) : null}
              {card.image ? (
                <img className="depth-card-rail__image" src={card.image} alt="" />
              ) : (
                <span className="depth-card-rail__face">
                  {/* tagBeforeMeaning 的卡（词汇积累）：词 → 音标 → 词性+释义，
                     词性跟着释义走，卡顶不再单独占一行。别的卡保持原样。 */}
                  {card.tag && !card.tagBeforeMeaning ? (
                    <span className="depth-card-rail__tag">{card.tag}</span>
                  ) : null}
                  <span className="depth-card-rail__word">{card.word}</span>
                  {card.phonetic ? (
                    <span className="depth-card-rail__phonetic">
                      {card.phonetic}
                    </span>
                  ) : null}
                  {card.meaning ? (
                    <span className="depth-card-rail__meaning">
                      {card.tag && card.tagBeforeMeaning ? (
                        <i className="depth-card-rail__pos">{card.tag}</i>
                      ) : null}
                      {card.meaning}
                    </span>
                  ) : null}
                  {typeof card.rounds === "number" ? (
                    <span className="depth-card-rail__rounds">
                      {card.rounds} 轮
                    </span>
                  ) : null}
                </span>
              )}
            </div>
          ),
        };
      }),
    [items],
  );

  const handleChange = useCallback((index: number) => {
    activeRef.current = index;
  }, []);

  /**
   * 点正对着的那张（`data-front` 的那张）就打开它；
   * 点后面那些，交给转盘自己把人转到中间来。
   * 拖动那一松手浏览器会把 click 投给盘子（指针被转盘收走了），这里就落空，
   * 不会把刚拖过去的那张又打开一次。
   */
  const handleClick = useCallback(
    (event: MouseEvent<HTMLDivElement>) => {
      const card = (event.target as HTMLElement).closest(".card-panorama__card");
      if (!card || card.getAttribute("data-front") !== "true") return;
      const item = items[activeRef.current];
      if (item) onSelect?.(item);
    },
    [items, onSelect],
  );

  /** 转盘自己的根节点只认左右方向键，回车交在这儿。 */
  const handleKeyDown = useCallback(
    (event: KeyboardEvent<HTMLDivElement>) => {
      if (event.key !== "Enter" && event.key !== " ") return;
      const item = items[activeRef.current];
      if (!item) return;
      event.preventDefault();
      onSelect?.(item);
    },
    [items, onSelect],
  );

  if (items.length === 0) {
    return (
      <div
        className={["depth-card-rail", "depth-card-rail--empty", className]
          .filter(Boolean)
          .join(" ")}
      >
        <p className="depth-card-rail__empty">{emptyLabel}</p>
      </div>
    );
  }

  return (
    <div
      className={["depth-card-rail", className].filter(Boolean).join(" ")}
      onClick={handleClick}
      onKeyDown={handleKeyDown}
    >
      <CardPanorama
        items={data}
        cardWidth={cardWidth}
        cardHeight={cardHeight}
        /* 和书房里别处的卡一个圆角。 */
        radius={14}
        /* 退到后面的卡压上来的那层墨：跟着当前皮肤走，不是本体默认那个深绿。 */
        tint="var(--theme-ink, #2f3a35)"
        label="卡片盘"
        initialIndex={initialIndex}
        onChange={handleChange}
        className="depth-card-rail__carousel"
      />
      {hint ? <p className="depth-card-rail__hint">{hint}</p> : null}
    </div>
  );
}

export default DepthCardRail;
